#!/usr/bin/env python3
"""Two-level glue for a split certificate already generated by gen_split.py (and its G files
compiled), without re-running any sub-check:

usage: gen_hier.py CERTDIR NAME EXPR UPPER BOUND NFILES     (same arguments as gen_split.py)

For each group file Gk (which must be a whole subtree of the top tree) writes Hk.lean: the
subtree `t`, its box `env`, `midsOK` (kernel), `t.jobs env = Gk.jobs` (rfl) and
`sub : checkC2 … (t.toCert d) env = true` (Top.sound + Gk.ok). Hier.lean glues the Hk.sub with
`TopC.sound` (split/TopC.lean) and realfp's soundness (`proveC_le/ge`). The one-level Main.lean
of gen_split does the same with a single `rfl` over all jobs, which does not scale past ~10^4 jobs."""
import os, sys, re
certdir, name, expr, upper, bound, nfiles = sys.argv[1:7]
nfiles = int(nfiles)
here = os.path.dirname(os.path.abspath(__file__)); outdir = os.path.join(here, name)
lines = [l.split() for l in open(os.path.join(certdir, 'top.txt')) if l.strip() and not l.startswith('#')]
hdr = open(os.path.join(certdir, 'top.txt')).readline().strip()
d = int(hdr.split(' dim ')[1].split()[0])
LO, HI = 0xBFF0000000000000, 0x3FF0000000000000
pos = 0; jobs = []
def parse(env):
    global pos
    t = lines[pos]; pos += 1
    if t[0] == 'S':
        i, m = int(t[1]), int(t[2])
        a = len(jobs)
        l = parse([(x if j != i else (x[0], m)) for j, x in enumerate(env)])
        r = parse([(x if j != i else (m, x[1])) for j, x in enumerate(env)])
        return ('S', i, m, l, r, a, len(jobs), env)
    k = len(jobs); jobs.append((int(t[1]), [int(x) for x in t[2:2 + d]], t[2 + d]))
    return ('J', k, k, k + 1, env)
root = parse([(LO, HI)] * d)
size = [1 + (os.path.getsize(os.path.join(certdir, j[2])) if j[2] != '0' else 0) for j in jobs]
tot = sum(size); grp = []; acc = 0
for k in range(len(jobs)):
    grp.append(min(nfiles - 1, acc * nfiles // tot)); acc += size[k]
groups = sorted(set(grp)); gname = {g: f"G{i:02d}" for i, g in enumerate(groups)}
rng = {g: (grp.index(g), len(grp) - grp[::-1].index(g)) for g in groups}
def lo_hi(n): return (n[5], n[6]) if n[0] == 'S' else (n[2], n[3])
def term(n, G):
    if n[0] == 'S':
        return f".split {n[1]} {n[2]}\n ({term(n[3], G)})\n ({term(n[4], G)})"
    k = n[1]; l0, cs0, fn = jobs[k]
    return f".sub {l0} {cs0} " + ('"0"' if fn == '0' else f"{G}.h{k}")
sub = {}
def find(n):  # map each group to the node spanning exactly its jobs
    a, b = lo_hi(n)
    for g in groups:
        if rng[g] == (a, b): sub[g] = n; return
    if n[0] == 'S': find(n[3]); find(n[4])
    else: raise SystemExit(f"job {n[1]}: its group is not a subtree")
find(root)
assert len(sub) == len(groups), "some group is not a subtree"
ub = upper == 'true'
cexpr = f"(KI.ofRat ({bound})).{'lo' if ub else 'hi'}"
gexpr = f"(if {upper} then gLe {cexpr} else gGe {cexpr})"
ns = f"ManyBox.Split.{name}"
def envs(env): return "[" + ", ".join(f"⟨{a}, {b}⟩" for a, b in env) + "]"
for g in groups:
    G = gname[g]; H = 'H' + G[1:]; n = sub[g]
    with open(os.path.join(outdir, f"{H}.lean"), 'w') as f:
        f.write(f"import split.{name}.{G}\nimport split.TopC\nopen Interval64.KF ManyBox\n"
                "set_option maxHeartbeats 0\nset_option maxRecDepth 100000\n\n")
        f.write(f"/-! Group {G} of `{name}` as one subtree (generated by gen_hier.py). -/\n\n")
        f.write(f"namespace {ns}.{H}\n\n")
        f.write(f"noncomputable def t : Top :=\n{term(n, G)}\n\n")
        f.write(f"def env : List KI := {envs(n[-1])}\n\n")
        f.write("theorem midsOK : t.midsOK = true := by decide +kernel\n\n")
        f.write(f"theorem jobs_eq : t.jobs env = {G}.jobs := rfl\n\n")
        f.write(f"theorem sub : checkC2 (compile {expr}) {gexpr} (t.toCert {d}) env = true :=\n"
                f"  Top.sound _ {upper} _ {d} t env midsOK (by rw [jobs_eq]; exact {G}.ok)\n\n")
        f.write(f"end {ns}.{H}\n")
def term2(n):
    for g in groups:
        if sub[g] is n: return f".leaf ({'H' + gname[g][1:]}.t.toCert {d})"
    return f".split {n[1]} {n[2]}\n ({term2(n[3])})\n ({term2(n[4])})"
Hs = ['H' + gname[g][1:] for g in groups]
with open(os.path.join(outdir, "Hier.lean"), 'w') as f:
    f.write("import ManyBoxCert\nimport ManyBoxProbs\nimport split.TopC\n")
    for H in Hs: f.write(f"import split.{name}.{H}\n")
    f.write("open Interval64.KF ManyBox\nset_option profiler true\nset_option profiler.threshold 200\n"
            "set_option maxHeartbeats 0\nset_option maxRecDepth 100000\n\n")
    f.write(f"/-! Split certificate `{name}`: {hdr}\n    {len(jobs)} sub-checks in {len(groups)} files, "
            "glued in two levels (gen_hier.py). -/\n\n")
    f.write(f"namespace {ns}\n\n")
    f.write(f"noncomputable def top2 : TopC :=\n{term2(root)}\n\n")
    f.write(f"def env0 : List KI := {envs(root[-1])}\n\n")
    f.write(f"theorem env0_eq : boxes (V2.cube {d}) = env0 := by decide +kernel\n\n")
    f.write("theorem midsOK2 : top2.midsOK = true := by decide +kernel\n\n")
    f.write("theorem leaves_eq : top2.leaves env0 = [" +
            ", ".join(f"({H}.t.toCert {d}, {H}.env)" for H in Hs) + "] := rfl\n\n")
    nest = "trivial"
    for H in reversed(Hs): nest = f"⟨{H}.sub, {nest}⟩"
    f.write(f"theorem all : checkC2 (compile {expr}) {gexpr} top2.toCert env0 = true :=\n"
            f"  TopC.sound _ _ top2 env0 midsOK2 (by rw [leaves_eq]; exact {nest})\n\n")
    rel = (f"{expr}.denote xs ≤ (({bound} : ℚ) : ℝ)" if ub else f"(({bound} : ℚ) : ℝ) ≤ {expr}.denote xs")
    f.write(f"/-- The claim on the whole cube, from {len(jobs)} sub-checks in {len(groups)} files. -/\n")
    f.write(f"theorem bound2 (xs : List ℝ) (hxs : RealFP.InBoxes xs (V2.cube {d})) : {rel} := by\n"
            f"  have h := all\n  rw [← env0_eq] at h\n"
            f"  simp only [{'' if ub else 'Bool.false_eq_true, '}↓reduceIte, checkC2_compile] at h\n"
            f"  exact proveC_{'le' if ub else 'ge'} {expr} (V2.cube {d}) ({bound}) _ h xs hxs\n\n")
    f.write(f"end {ns}\n\n#print axioms {ns}.bound2\n")
print(f"{len(groups)} H files + Hier.lean in {outdir}")
